create table if not exists public.ils_rls_dependency_mapping_audit (id uuid primary key default gen_random_uuid(), table_name text not null, identity_columns text, fk_count integer not null default 0, access_class text not null, decision text not null, rationale text not null, created_at timestamptz not null default now(), unique(table_name));
insert into public.ils_rls_dependency_mapping_audit(table_name,identity_columns,fk_count,access_class,decision,rationale)
select c.relname, coalesce(string_agg(distinct a.attname,',' order by a.attname) filter(where a.attname in ('user_id','customer_id','professional_user_id','created_by','passport_id','matter_id','associate_id','recipient_ref')),'') ,count(distinct con.oid),
case when c.relname like 'ils_%notification%' or c.relname like 'ils_%payment%' then 'CRITICAL_INTERNAL' when coalesce(string_agg(distinct a.attname,',' order by a.attname) filter(where a.attname in ('user_id','customer_id','professional_user_id','created_by','passport_id','matter_id','associate_id','recipient_ref')),'')<>'' then 'IDENTITY_LINKED' else 'INTERNAL_REFERENCE' end,
case when c.relname in ('ils_chronology_summaries','ils_complaint_passport_events','ils_complaint_reminders','ils_customer_notifications','ils_document_readiness_results','ils_evidence_pack_items','ils_b2b_work_items','ils_professional_work_items','ils_associate_activation_progress','ils_associate_help_requests','ils_associate_learning_progress','ils_associate_onboarding_status','ils_associate_quality_events','ils_associate_role_history','ils_associate_payout_ledger','ils_associate_payout_events','ils_notification_orchestration_runs','ils_notification_security_events','ils_notification_trigger_events','ils_payment_projection_integrity_events','ils_payment_reconciliation','ils_payment_refund_cases','ils_payment_transactions','ils_professional_guide_access','ils_professional_guide_versions','ils_upi_verifiers','ils_work_allocation_events','ils_work_deadlines','ils_work_queue_scores','ils_work_reminder_events') then 'HOLD_REVIEW' else 'BACKEND_ONLY_REVIEW' end,
case when c.relname in ('ils_chronology_summaries','ils_complaint_passport_events','ils_complaint_reminders','ils_customer_notifications','ils_document_readiness_results','ils_evidence_pack_items') then 'Passport ownership chain exists but customer-facing policy must be explicitly designed.' when coalesce(string_agg(distinct a.attname,',' order by a.attname) filter(where a.attname in ('user_id','customer_id','professional_user_id','created_by','passport_id','matter_id','associate_id','recipient_ref')),'')<>'' then 'Identity-bearing internal/workforce data; do not expose until exact role boundary is defined.' else 'No direct identity owner; keep backend-only until a safe public access contract exists.' end
from pg_class c join pg_namespace n on n.oid=c.relnamespace left join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_constraint con on con.conrelid=c.oid and con.contype='f' where n.nspname='public' and c.relkind='r' and c.relrowsecurity and not exists(select 1 from pg_policies p where p.schemaname='public' and p.tablename=c.relname) group by c.relname
on conflict(table_name) do update set identity_columns=excluded.identity_columns,fk_count=excluded.fk_count,access_class=excluded.access_class,decision=excluded.decision,rationale=excluded.rationale,created_at=now();